class Book(var title: String) extends KeyedEntity[Long] {
    val id: Long = 0
}

object Library extends Schema {
    val books = table[Book]("books")
}

val book = new Book("The Hobbit")
transaction {
    Library.books.insert(book)
    book.title = "The Hobbit: illustrated"
    Library.books.update(book)
}
